    n = len(matrix)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            result[j][n - 1 - i] = matrix[i][j]                            # place each element directly into its final rotated position
    for i in range(n):
        matrix[i] = result[i]                                               # copy the rotated result back, since the problem requires in-place modification
    return matrix


