import java.util.*;

public class Main {
    void rotate(int[][] matrix) {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int temp = matrix[i][j];
                matrix[i][j] = matrix[j][i];                                      // transpose: swap across the main diagonal, in place
                matrix[j][i] = temp;
            }
        }
        for (int[] row : matrix) {
            int left = 0, right = n - 1;
            while (left < right) {
                int temp = row[left];
                row[left] = row[right];                                            // reverse each row, completing the 90-degree clockwise rotation
                row[right] = temp;
                left++;
                right--;
            }
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[][] matrix = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
        solution.rotate(matrix);
        for (int[] row : matrix) System.out.println(Arrays.toString(row));
    }
}

